 @Entity
 @Table(name = "discussion_posts")
 public class DiscussionPost {

     @Id
     @Column(nullable = false, updatable = false)
     private UUID id = UUID.randomUUID();

     @Column(nullable = false, length = 200)
     private String title;

     @Lob
