                 .andReturn()
                 .getResponse()
                 .getContentAsString();
         return extractId(response);
     }

     private UUID extractId(String response) {
         Matcher matcher = Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(response);
